<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use App\Services\PeriodGuard;
class SocialSupportController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('upbringing_head')||$r->user()->hasRole('social_teacher'),403);}
 public function index(Request $r){$this->ok($r);$q=DB::table('student_social_statuses as ss')->join('students as s','s.id','=','ss.student_id')->join('student_social_categories as c','c.id','=','ss.category_id')->leftJoin('study_groups as g','g.id','=','s.current_group_id')->select('ss.*','s.last_name','s.first_name','s.middle_name','g.name as group_name','c.name as category_name','c.code as category_code');if($r->filled('group'))$q->where('s.current_group_id',$r->integer('group'));if($r->filled('category'))$q->where('ss.category_id',$r->integer('category'));if($r->filled('state'))$q->where('ss.status',$r->state);$rows=$q->orderBy('s.last_name')->get();return view('upbringing.social-statuses',['rows'=>$rows,'students'=>DB::table('students')->where('status','active')->orderBy('last_name')->get(),'groups'=>DB::table('study_groups')->where('active',1)->orderBy('name')->get(),'categories'=>DB::table('student_social_categories')->where('active',1)->orderBy('name')->get()]);}
 public function category(Request $r){$this->ok($r);$d=$r->validate(['code'=>'required|string|max:80|unique:student_social_categories,code','name'=>'required|string|max:255','note'=>'nullable|string|max:3000']);DB::table('student_social_categories')->insert($d+['active'=>1,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Социальная категория добавлена');}
 public function store(Request $r){$this->ok($r);$d=$r->validate(['student_id'=>'required|exists:students,id','category_id'=>'required|exists:student_social_categories,id','valid_from'=>'nullable|date','valid_until'=>'nullable|date|after_or_equal:valid_from','document_type'=>'nullable|string|max:150','document_number'=>'nullable|string|max:150','document_date'=>'nullable|date','issuer'=>'nullable|string|max:255','note'=>'nullable|string|max:5000']);DB::table('student_social_statuses')->insert($d+['status'=>'active','created_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Социальный статус зарегистрирован');}
 public function close(Request $r,$id){$this->ok($r);abort_unless(DB::table('student_social_statuses')->where('id',$id)->exists(),404);DB::table('student_social_statuses')->where('id',$id)->update(['status'=>'closed','valid_until'=>$r->input('valid_until',today()),'updated_at'=>now()]);return back()->with('success','Социальный статус закрыт');}
}